// Pokédex generated by tools/build_pokedex.py, fusion sprites by tools/extract_sprites.py.
const POKEAPI_SPRITES = "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites";
const FUSION_CDN = "https://ifd-spaces.sfo2.cdn.digitaloceanspaces.com";
// The online CDN only has sprites (custom and auto-generated) for the first 501 Infinite Fusion ids.
const CDN_MAX_ID = 501;

export const TIERS = [
  null,
  { id: 1, name: "Poké Ball", item: "poke-ball", weight: 52 },
  { id: 2, name: "Super Ball", item: "great-ball", weight: 28 },
  { id: 3, name: "Hyper Ball", item: "ultra-ball", weight: 13 },
  { id: 4, name: "Honor Ball", item: "premier-ball", weight: 5.5 },
  { id: 5, name: "Master Ball", item: "master-ball", weight: 1.5 },
];

export const SHINY_ODDS = 1 / 128;

export const TYPES_FR = {
  normal: ["Normal", "#a8a77a"], fire: ["Feu", "#ee8130"], water: ["Eau", "#6390f0"],
  electric: ["Électrik", "#d4b000"], grass: ["Plante", "#5fa83a"], ice: ["Glace", "#6fc6c2"],
  fighting: ["Combat", "#c22e28"], poison: ["Poison", "#a33ea1"], ground: ["Sol", "#c9a748"],
  flying: ["Vol", "#8f7fd8"], psychic: ["Psy", "#f95587"], bug: ["Insecte", "#8f9c1a"],
  rock: ["Roche", "#b6a136"], ghost: ["Spectre", "#735797"], dragon: ["Dragon", "#6f35fc"],
  dark: ["Ténèbres", "#705746"], steel: ["Acier", "#9a9ab8"], fairy: ["Fée", "#d685ad"],
};

// Same order as pokedex.json stats. In Infinite Fusion the head dominates
// HP / Sp. Atk / Sp. Def and the body dominates the others.
const STATS = [
  { label: "PV", head: true }, { label: "Attaque", head: false }, { label: "Défense", head: false },
  { label: "Att. Spé", head: true }, { label: "Déf. Spé", head: true }, { label: "Vitesse", head: false },
];

export let pokedex = [];
export const byId = new Map();
export const byTier = [[], [], [], [], [], []];

export async function loadPokedex() {
  pokedex = await fetch("data/pokedex.json").then((r) => r.json());
  for (const p of pokedex) {
    byId.set(p.id, p);
    byTier[p.tier].push(p);
  }
}

export const ballSprite = (tier) => `${POKEAPI_SPRITES}/items/${TIERS[tier].item}.png`;
export const officialSprite = (p, shiny = false) =>
  `${POKEAPI_SPRITES}/pokemon/${shiny ? "shiny/" : ""}${p.sprite}.png`;
export const cryUrl = (p) => `https://raw.githubusercontent.com/PokeAPI/cries/main/cries/pokemon/latest/${p.nat}.ogg`;

export const normalize = (s) => s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
export const label = (p) => (p.form ? `${p.fr} (${p.form})` : p.fr);

export function matches(p, term) {
  const t = normalize(term.trim());
  if (!t) return true;
  if (/^\d+$/.test(t)) return String(p.nat) === t;
  const haystack = normalize(`${label(p)} ${p.en}`);
  return t.split(/\s+/).every((w) => haystack.includes(w));
}

const spriteIndexCache = new Map();
export function getSpriteIndex(headId) {
  if (!spriteIndexCache.has(headId)) {
    spriteIndexCache.set(
      headId,
      fetch(`data/sprites/${headId}.json`).then((r) => (r.ok ? r.json() : {})).catch(() => ({})),
    );
  }
  return spriteIndexCache.get(headId);
}

// custom: hand-drawn sprites ("" = main, letters = alternates); auto: the CDN has a generated one.
export async function fusionOptions(headId, bodyId) {
  const index = await getSpriteIndex(headId);
  const custom = Object.entries(index[bodyId] || {})
    .map(([variant, artist]) => ({ variant, artist }))
    .sort((a, b) => a.variant.length - b.variant.length || a.variant.localeCompare(b.variant));
  return { custom, auto: headId <= CDN_MAX_ID && bodyId <= CDN_MAX_ID };
}

// variant === null means the auto-generated sprite. Hand-drawn sprites come from the CDN
// when it knows both ids, otherwise from sprites/custom (see tools/extract_sprites.py).
export function fusionSpriteUrl(headId, bodyId, variant) {
  const file = `${headId}.${bodyId}${variant ?? ""}.png`;
  if (variant === null) return `${FUSION_CDN}/generated/${file}`;
  return headId <= CDN_MAX_ID && bodyId <= CDN_MAX_ID ? `${FUSION_CDN}/custom/${file}` : `sprites/custom/${file}`;
}

export function fusionName(head, body) {
  const a = head.fr, b = body.fr;
  return a.slice(0, Math.ceil(a.length / 2)) + b.slice(Math.floor(b.length / 2)).toLowerCase();
}

export function fusionTypes(head, body) {
  const primary = head.types[0];
  let secondary = body.types[1] || body.types[0];
  if (secondary === primary) secondary = body.types[0];
  return secondary === primary ? [primary] : [primary, secondary];
}

export function fusionStats(head, body) {
  return STATS.map((s, i) => {
    const [major, minor] = s.head ? [head.stats[i], body.stats[i]] : [body.stats[i], head.stats[i]];
    return { label: s.label, value: Math.floor((2 * major) / 3 + minor / 3) };
  });
}

export const baseStats = (p) => STATS.map((s, i) => ({ label: s.label, value: p.stats[i] }));

// Average of both parents rounded up, +1 when both share the same tier (Super Ball or above).
export function fusionTier(a, b) {
  return Math.min(5, Math.ceil((a + b) / 2) + (a === b && a >= 2 ? 1 : 0));
}

export function typeBadges(types) {
  return `<div class="types">${types
    .map((t) => `<span class="type" style="--c:${TYPES_FR[t][1]}">${TYPES_FR[t][0]}</span>`)
    .join("")}</div>`;
}

export function statsTable(stats) {
  const total = stats.reduce((s, x) => s + x.value, 0);
  return `<table class="stats">${stats
    .map((s) => `<tr><td>${s.label}</td><td class="val">${s.value}</td>
      <td><div class="bar"><span style="width:${Math.min(100, (s.value / 180) * 100)}%"></span></div></td></tr>`)
    .join("")}<tr class="total"><td>Total</td><td class="val">${total}</td><td></td></tr></table>`;
}
